//! Generated by tools/gen_menu.py: the menu's backing controls, in the order its
//! buttons press them (`mod.control:<index>`). Tabs come first.

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Kind {
    Toggle,
    Slider,
    Choice,
    Keybind,
    Button,
    /// A second button pressing another control; sent as a plain button nobody presses.
    #[allow(dead_code)]
    Alias,
}

pub const TABS: [&str; 1] = ["Settings"];

pub const CONTROLS: [(Kind, &str, &str); 11] = [
    (Kind::Button, "tab_0", "Settings"),
    (Kind::Toggle, "show", "Show the day"),
    (Kind::Toggle, "show_time", "Show the time"),
    (Kind::Choice, "color", "Color"),
    (Kind::Slider, "scale", "Size"),
    (Kind::Toggle, "shadow", "Shadow"),
    (Kind::Button, "move", "Move with the mouse"),
    (Kind::Button, "reset_position", "Back above the hotbar"),
    (Kind::Keybind, "menu_key", "Menu key"),
    (Kind::Button, "kofi", "Support me on Ko-fi"),
    (Kind::Button, "move_done", "Done"),
];

/// The document, already escaped to sit inside a JSON string.
pub const DOCUMENT_ESCAPED: &str = include_str!("menu.escaped");

pub const SCREEN: &str = "daycounter.menu";
/// Whether the menu has a "move with the mouse" mode.
pub const MOVE: bool = true;
pub const WIDTH: u32 = 400;
pub const HEIGHT: u32 = 240;
